window.__pendenteRecuperacaoSenha = false;
(function detectarRecuperacaoCedo() {
  try {
    var u = new URL(window.location.href);
    var h = window.location.hash || '';
    if (u.searchParams.get('recuperar') === '1'
      || u.searchParams.get('type') === 'recovery'
      || u.searchParams.get('token_hash')
      || h.indexOf('type=recovery') >= 0
      || (h.indexOf('access_token') >= 0 && h.indexOf('type=recovery') >= 0)
      || h.indexOf('type=recovery') >= 0) {
      window.__pendenteRecuperacaoSenha = true;
    }
    // recovery token in hash type=
    if (h.indexOf('type=recovery') >= 0) window.__pendenteRecuperacaoSenha = true;
  } catch (e) {}
})();


