 function urlRetornoCadastro(status) {
 const u = new URL(window.location.href);

 ['cadastro_mp', 'payment_id', 'status', 'collection_id', 'collection_status',
 'preference_id', 'external_reference', 'payment_type', 'merchant_order_id',
 'site_id', 'processing_mode', 'merchant_account_id'].forEach(function(k) {
 u.searchParams.delete(k);
 });
 u.searchParams.set('cadastro_mp', status);
 return u.toString();
 }

 function isMercadoPagoSandbox(mp) {
 mp = mp || ((TAXA_CADASTRO && TAXA_CADASTRO.mercadoPago) ? TAXA_CADASTRO.mercadoPago : {}) || {};

 if (mp.sandbox === true) return true;
 if (mp.sandbox === false) return false;
 const token = String(mp.accessToken || '').trim();
 if (!token) return true;

 if (/^TEST-/i.test(token)) return true;
 if (/sandbox/i.test(token)) return true;

 if (/^APP_USR-/i.test(token)) return false;
 return false;
 }

 function escolherInitPointMercadoPago(pref, mp) {
 pref = pref || {};
 const sandbox = isMercadoPagoSandbox(mp);
 if (sandbox) {
 return pref.sandbox_init_point || pref.init_point || '';
 }
 return pref.init_point || pref.sandbox_init_point || '';
 }

 async function criarPreferenciaMercadoPago(dados) {
 const mp = (TAXA_CADASTRO && TAXA_CADASTRO.mercadoPago) ? TAXA_CADASTRO.mercadoPago : {};
 const valor = Number(TAXA_CADASTRO.valor) || 0;
 const body = {
 items: [{
 id: 'taxa-cadastro-aldineicar',
 title: TAXA_CADASTRO.descricao || 'Ativacao ALDINEICAR',
 description: 'Taxa de ativacao da conta ' + (dados.email || ''),
 quantity: 1,
 currency_id: 'BRL',
 unit_price: valor
 }],
 payer: {
 name: dados.nome || '',
 email: dados.email || ''
 },
 external_reference: dados.txid || ('CAD-' + Date.now()),
 statement_descriptor: 'ALDINEICAR',
 back_urls: {
 success: urlRetornoCadastro('success'),
 failure: urlRetornoCadastro('failure'),
 pending: urlRetornoCadastro('pending')
 },
 auto_return: 'approved',
 metadata: {
 tipo: 'taxa_cadastro',
 email: dados.email || '',
 nome: dados.nome || ''
 }
 };

 if (mp.preferenceProxyUrl) {
 const headers = { 'Content-Type': 'application/json' };
 try {
 if (typeof supabaseKey === 'string' && supabaseKey) {
 headers['Authorization'] = 'Bearer ' + supabaseKey;
 headers['apikey'] = supabaseKey;
 }
 } catch (e) {}
 const res = await fetch(mp.preferenceProxyUrl, {
 method: 'POST',
 headers: headers,
 body: JSON.stringify(body)
 });
 const json = await res.json().catch(function() { return {}; });
 if (!res.ok) throw new Error(json.message || json.error || ('HTTP ' + res.status));
 return json;
 }

 if (!mp.accessToken) {
 throw new Error('Pagamento online temporariamente indisponível. Use o PIX manual ou fale com o suporte.');
 }

 const res = await fetch('https://api.mercadopago.com/checkout/preferences', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Authorization': 'Bearer ' + mp.accessToken
 },
 body: JSON.stringify(body)
 });
 const json = await res.json().catch(function() { return {}; });
 if (!res.ok) {
 const msg = (json && json.message) || (json && json.error) || ('Erro MP HTTP ' + res.status);
 throw new Error(msg);
 }
 return json;
 }

 async function verificarPagamentoMercadoPago(paymentId) {
 const mp = (TAXA_CADASTRO && TAXA_CADASTRO.mercadoPago) ? TAXA_CADASTRO.mercadoPago : {};
 if (!paymentId) return null;
 if (mp.statusProxyUrl) {
 try {
 const headers = { 'Content-Type': 'application/json' };
 if (typeof supabaseKey === 'string' && supabaseKey) {
 headers['Authorization'] = 'Bearer ' + supabaseKey;
 headers['apikey'] = supabaseKey;
 }
 const res = await fetch(mp.statusProxyUrl, {
 method: 'POST',
 headers: headers,
 body: JSON.stringify({ payment_id: paymentId })
 });
 if (!res.ok) return null;
 return await res.json();
 } catch (e) {
 console.warn('verify mp proxy', e);
 return null;
 }
 }
 if (!mp.accessToken) return { id: paymentId, status: 'unknown' };
 try {
 const res = await fetch('https://api.mercadopago.com/v1/payments/' + encodeURIComponent(paymentId), {
 headers: { 'Authorization': 'Bearer ' + mp.accessToken }
 });
 if (!res.ok) return null;
 return await res.json();
 } catch (e) {
 console.warn('verify mp', e);
 return null;
 }
 }

 async function buscarPagamentoMercadoPagoPorReferencia(externalRef) {
 const mp = (TAXA_CADASTRO && TAXA_CADASTRO.mercadoPago) ? TAXA_CADASTRO.mercadoPago : {};
 if (!externalRef) return null;
 if (mp.statusProxyUrl) {
 try {
 const headers = { 'Content-Type': 'application/json' };
 if (typeof supabaseKey === 'string' && supabaseKey) {
 headers['Authorization'] = 'Bearer ' + supabaseKey;
 headers['apikey'] = supabaseKey;
 }
 const res = await fetch(mp.statusProxyUrl, {
 method: 'POST',
 headers: headers,
 body: JSON.stringify({ external_reference: externalRef })
 });
 if (!res.ok) return null;
 const json = await res.json();
 if (!json || json.status === 'not_found') return null;
 return json;
 } catch (e) {
 console.warn('buscar mp proxy', e);
 return null;
 }
 }
 if (!mp.accessToken) return null;
 try {
 const url = 'https://api.mercadopago.com/v1/payments/search?sort=date_created&criteria=desc&external_reference=' + encodeURIComponent(externalRef);
 const res = await fetch(url, { headers: { 'Authorization': 'Bearer ' + mp.accessToken } });
 if (!res.ok) return null;
 const json = await res.json();
 const results = (json && json.results) ? json.results : [];
 if (!results.length) return null;

 var approved = results.find(function(p) { return p && p.status === 'approved'; });
 return approved || results[0];
 } catch (e) {
 console.warn('search mp', e);
 return null;
 }
 }

 let __mpPollTimer = null;
 function pararPollMercadoPago() {
 if (__mpPollTimer) {
 clearInterval(__mpPollTimer);
 __mpPollTimer = null;
 }
 }

 function iniciarPollAprovacaoMercadoPago(opts) {
 opts = opts || {};
 pararPollMercadoPago();
 var tentativas = 0;
 var maxTentativas = opts.maxTentativas || 40;
 var intervalMs = opts.intervalMs || 3000;
 var stTxt = document.getElementById('signupMpStatusTxt');
 var btnConf = document.getElementById('btnSignupConfirmarPagamento');

 async function tick() {
 tentativas++;
 var pend = carregarSignupPendente();
 if (!pend) {
 pararPollMercadoPago();
 return;
 }
 if (stTxt) {
 stTxt.innerHTML = 'Aguardando confirmação do PIX no Mercado Pago...<br><span style="color:#94a3b8;font-size:12px;font-weight:500;">Isso pode levar alguns segundos após o pagamento. (' + tentativas + '/' + maxTentativas + ')</span>';
 }
 var pag = null;
 if (pend.mpPaymentId) {
 pag = await verificarPagamentoMercadoPago(pend.mpPaymentId);
 }
 if (!pag || pag.status !== 'approved') {
 pag = await buscarPagamentoMercadoPagoPorReferencia(pend.txid || pend.mpPreferenceId || '');
 }
 if (pag && pag.status === 'approved') {
 pararPollMercadoPago();
 pend.mpPaymentId = String(pag.id || pend.mpPaymentId || '');
 salvarSignupPendente(pend);
 if (stTxt) stTxt.innerHTML = 'PIX <b style="color:#22c55e;">aprovado</b>! Liberando sua conta...';
 if (typeof mostrarToast === 'function') mostrarToast('PIX aprovado! Liberando conta...', 'sucesso');
 await confirmarPagamentoECriarConta({ mpAprovado: true, forcar: true });
 return;
 }
 if (tentativas >= maxTentativas) {
 pararPollMercadoPago();
 if (stTxt) stTxt.innerHTML = 'Ainda não vimos a confirmação automática.<br>Se o PIX já caiu, toque no botão abaixo.';
 if (btnConf) {
 btnConf.style.display = 'block';
 btnConf.textContent = '✓ Já paguei — liberar minha conta';
 btnConf.onclick = function() { confirmarPagamentoECriarConta({ mpAprovado: true, forcar: true }); };
 }
 }
 }

 tick();
 __mpPollTimer = setInterval(tick, intervalMs);
 }

