 document.addEventListener('DOMContentLoaded', () => {
 try { if (typeof verificarModoCliente === 'function') verificarModoCliente(); } catch (e) { console.warn(e); }
 try { toggleTab('login'); } catch (e) { console.warn(e); }
 try { if (typeof processarRetornoMercadoPago === 'function') processarRetornoMercadoPago(); } catch (e) { console.warn(e); }
 try { if (typeof atualizarUITaxaCadastro === 'function') atualizarUITaxaCadastro(); } catch (e) {}

 if (!supabaseClient || !supabaseClient.auth) {
 console.error('Supabase não disponível — login/cadastro desabilitados até atualizar a página.');
 return;
 }

 supabaseClient.auth.onAuthStateChange(async (event, session) => {
 try {
 if (window.__modoClienteVitrine) {
 const login = document.getElementById('loginOverlay');
 const app = document.getElementById('appContainer');
 if (login) login.style.display = 'none';
 if (app) app.style.display = 'none';
 return;
 }

 // Recuperação de senha: NÃO entrar no app — só tela de nova senha
 if (event === 'PASSWORD_RECOVERY') {
 window.__pendenteRecuperacaoSenha = true;
 }
 if (window.__pendenteRecuperacaoSenha || event === 'PASSWORD_RECOVERY') {
 const loginEl = document.getElementById('loginOverlay');
 if (loginEl) loginEl.style.display = 'flex';
 if (typeof mostrarTelaNovaSenha === 'function') mostrarTelaNovaSenha();
 return;
 }

 if (session && session.user) {
 try {
   if (typeof verificarManutencaoAntesLogin === 'function') {
     var stM2 = await verificarManutencaoAntesLogin();
     if (stM2 && stM2.manutencao) {
       var em2 = String(session.user.email || '').toLowerCase();
       var isAdm2 = (typeof isEmailAdmin === 'function' && isEmailAdmin(em2)) || em2 === 'nbdynei707@gmail.com';
       if (!isAdm2) {
         await supabaseClient.auth.signOut();
         alert(stM2.mensagem || 'Sistema em manutenção. Voltamos em breve.');
         return;
       }
     }
   }
 } catch (eM2) { console.warn(eM2); }
 await carregarDadosDoUsuario(session.user.id);
 try {
 if (typeof ativarMenuAdminSePermitido === 'function') {
 ativarMenuAdminSePermitido(session.user.email);
 }
 } catch (eAdm) { console.warn(eAdm); }
 try {
   if (typeof processarRetornoAssinatura === 'function') await processarRetornoAssinatura();
   if (typeof verificarAvisoAssinatura === 'function') await verificarAvisoAssinatura();
 } catch (eAss) { console.warn(eAss); }
 const loginEl = document.getElementById('loginOverlay');
 if (loginEl) loginEl.style.display = 'none';
 const abas = ['aba-materiais', 'aba-clientes', 'aba-historico', 'aba-maoobra'];
 const algumaAtiva = abas.some(id => {
 const el = document.getElementById(id);
 return el && el.style.display === 'block';
 });
 if (!algumaAtiva && typeof mostrarAba === 'function') mostrarAba('dashboard');
 } else {
 const loginEl = document.getElementById('loginOverlay');
 if (loginEl) loginEl.style.display = 'flex';
 toggleTab('login');
 }
 } catch (err) {
 console.error('onAuthStateChange', err);
 }
 });
 });

 function configurarResumoPorProfissao() {
 const prof = dadosOficina.profissao || 'pintor';

 const inModelo = document.getElementById('veiculoModelo');
 const inPlaca = document.getElementById('veiculoPlaca');
 const inAno = document.getElementById('veiculoAno');
 const inCor = document.getElementById('veiculoCor');

 if (!inModelo || !inPlaca || !inAno || !inCor) return;

 const lblModelo = inModelo.previousElementSibling;
 const lblPlaca = inPlaca.previousElementSibling;
 const lblAno = inAno.previousElementSibling;
 const lblCor = inCor.previousElementSibling;

 if (prof === 'mecanico') {
 if(lblModelo) lblModelo.innerText = "MODELO / MOTORIZAÇÃO";
 if(inModelo) inModelo.placeholder = "Modelo / Motorização";
 if(lblPlaca) lblPlaca.innerText = "PLACA";
 if(inPlaca) inPlaca.placeholder = "Placa";
 if(lblAno) lblAno.innerText = "ANO";
 if(inAno) inAno.placeholder = "Ano";
 if(lblCor) lblCor.innerText = "QUILOMETRAGEM (KM)";
 if(inCor) { inCor.placeholder = "Quilometragem (KM)"; inCor.type = "text"; }
 } else if (prof === 'eletricista') {
 if(lblModelo) lblModelo.innerText = "EDIFÍCIO";
 if(inModelo) inModelo.placeholder = "Edifício";

 if(lblPlaca) lblPlaca.innerText = "IDENTIFICAÇÃO / NÚMERO";
 if(inPlaca) inPlaca.placeholder = "Identificação / Número";

 if(lblAno) lblAno.innerText = "ÁREA m²";
 if(inAno) inAno.placeholder = "Área m²";

 if(lblCor) lblCor.innerText = "TIPO DE INSTALAÇÃO";
 if(inCor) { inCor.placeholder = "Tipo de Instalação"; inCor.type = "text"; }
 } else {
 if(lblModelo) lblModelo.innerText = "MODELO DO VEÍCULO";
 if(inModelo) inModelo.placeholder = "Modelo do Veículo";
 if(lblPlaca) lblPlaca.innerText = "PLACA";
 if(inPlaca) inPlaca.placeholder = "Placa";
 if(lblAno) lblAno.innerText = "ANO";
 if(inAno) inAno.placeholder = "Ano";
 if(lblCor) lblCor.innerText = "COR DO VEÍCULO / CÓDIGO";
 if(inCor) { inCor.placeholder = "Cor do Veículo / Código"; inCor.type = "text"; }
 }
}

 async function alterarStatus(index, novoStatus) {
 if (historico[index]) {
 // fluxo sequencial: grava status e atualiza dashboard (Concluído continua contando; Pago vai para Pagos)
 if (novoStatus === 'Pronto') novoStatus = 'Concluído';
 historico[index].status = novoStatus;
 if (novoStatus === 'Concluído') historico[index].concluido_em = new Date().toISOString();
 if (novoStatus === 'Pago') historico[index].pago_em = new Date().toISOString();
 renderHistorico();
 await salvarNoBanco();
 try { if (typeof renderDashboard === 'function') renderDashboard(); } catch (e) {}
 if (typeof mostrarToast === 'function') {
   if (novoStatus === 'Em Execução') mostrarToast('Status: Em execução', 'sucesso');
   else if (novoStatus === 'Concluído') mostrarToast('Status: Concluído (conta no dashboard)', 'sucesso');
   else if (novoStatus === 'Pago') mostrarToast('Status: Pago (conta em Pagos)', 'sucesso');
 }
 }
}

function mostrarToast(mensagem, tipo = 'sucesso') {
 let container = document.getElementById('toast-container');
 if (!container) {
 container = document.createElement('div');
 container.id = 'toast-container';
 document.body.appendChild(container);
 }

 const toast = document.createElement('div');
 toast.className = `toast toast-${tipo}`;

 let icone = '✅';
 if (tipo === 'erro') icone = '❌';
 if (tipo === 'aviso') icone = '⚠️';

 toast.innerHTML = `<span>${icone}</span> <span>${mensagem}</span>`;

 container.appendChild(toast);

 setTimeout(() => {
 toast.classList.add('toast-ativo');
 }, 10);

 setTimeout(() => {
 toast.classList.remove('toast-ativo');
 setTimeout(() => {
 toast.remove();
 }, 300);
 }, 3500);
}

