function calcularTotalCompraDinamica() {
 const inputQtd = document.getElementById('vendaQtd');
 const txtTotal = document.getElementById('vendaTotalExibicao');
 if (!inputQtd || !txtTotal) return;
 let qtd = parseInt(inputQtd.value) || 1;
 if (qtd > estoqueDisponivelSelecionado) {
 qtd = estoqueDisponivelSelecionado;
 inputQtd.value = qtd;
 }
 if (qtd < 1) { qtd = 1; inputQtd.value = 1; }
 txtTotal.innerText = 'R$ ' + (qtd * precoUnitarioSelecionado).toFixed(2);
}

function fecharModalCompraDinamica() {

 const modal = document.getElementById('modalCompraProdutoDinamico');
 if (modal) modal.remove();
}

function copiarPixCopiaCola() {
 const ta = document.getElementById('pixCopiaCola');
 if (!ta || !ta.value) return;
 navigator.clipboard.writeText(ta.value).then(function() {
 alert('Código PIX copiado!');
 }).catch(function() {
 ta.select();
 document.execCommand('copy');
 alert('Código PIX copiado!');
 });
}

function obterIdLojaAtual() {
 if (typeof idOficinaDaLojaAtual !== 'undefined' && idOficinaDaLojaAtual) return idOficinaDaLojaAtual;
 const p = new URLSearchParams(window.location.search);
 return p.get('id') || p.get('loja') || p.get('user_id') || null;
}

async function obterPixDaOficina(idDono) {
 try {
 const { data } = await supabaseClient.from('user_data').select('dados_oficina').eq('user_id', idDono).single();
 if (data && data.dados_oficina && data.dados_oficina.pix) {
 const pix = String(data.dados_oficina.pix).trim();
 if (pix) {
 return {
 chave: pix.replace(/\s/g, ''),
 nome: data.dados_oficina.nome || 'ALDINEICAR'
 };
 }
 }
 } catch (e) {}
 if (typeof dadosOficina !== 'undefined' && dadosOficina && dadosOficina.pix) {
 return {
 chave: String(dadosOficina.pix).replace(/\s/g, ''),
 nome: dadosOficina.nome || 'ALDINEICAR'
 };
 }
 return null;
}

function desenharQrSimples(payload) {
 const box = document.getElementById('pixQrBox');
 if (!box) return;
 box.innerHTML = '<p style="color:#a1a1aa;font-size:12px;text-align:center;padding:12px;">Carregando QR...</p>';

 function fallbackImg() {
 const img = document.createElement('img');
 img.width = 200; img.height = 200;
 img.style.borderRadius = '8px'; img.style.background = '#fff'; img.style.padding = '8px';
 img.src = 'https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=' + encodeURIComponent(payload);
 box.innerHTML = '';
 box.appendChild(img);
 }

 ensureQRCode().then(function() {
 box.innerHTML = '';
 const canvas = document.createElement('canvas');
 canvas.style.background = '#fff';
 canvas.style.borderRadius = '8px';
 canvas.style.padding = '8px';
 box.appendChild(canvas);
 QRCode.toCanvas(canvas, payload, { width: 200, margin: 2 }, function(err) {
 if (err) fallbackImg();
 });
 }).catch(function() {
 fallbackImg();
 });
}



/* ===== Loja: PIX automático via Mercado Pago ===== */
var __lojaPollTimer = null;
var __lojaVendaPendente = null;

function pararPollLojaPix() {
  if (__lojaPollTimer) {
    clearInterval(__lojaPollTimer);
    __lojaPollTimer = null;
  }
}

function salvarLojaVendaPendente(obj) {
  __lojaVendaPendente = obj;
  try { sessionStorage.setItem('aldineicar_loja_venda', JSON.stringify(obj)); } catch (e) {}
}

function carregarLojaVendaPendente() {
  if (__lojaVendaPendente) return __lojaVendaPendente;
  try {
    var raw = sessionStorage.getItem('aldineicar_loja_venda');
    if (raw) __lojaVendaPendente = JSON.parse(raw);
  } catch (e) {}
  return __lojaVendaPendente;
}

function limparLojaVendaPendente() {
  __lojaVendaPendente = null;
  try { sessionStorage.removeItem('aldineicar_loja_venda'); } catch (e) {}
}

async function criarPreferenciaLojaMP(dados) {
  var headers = { 'Content-Type': 'application/json' };
  if (typeof supabaseKey === 'string' && supabaseKey) {
    headers['Authorization'] = 'Bearer ' + supabaseKey;
    headers['apikey'] = supabaseKey;
  }
  var res = await fetch(LOJA_CRIAR_PREF_URL, {
    method: 'POST',
    headers: headers,
    body: JSON.stringify(dados)
  });
  var json = await res.json().catch(function() { return {}; });
  // 200 + modo manual = ok (oficina sem token)
  if (json && (json.modo === 'manual' || json.error === 'oficina_sem_mp')) return json;
  if (!res.ok) throw new Error(json.error || json.message || ('HTTP ' + res.status));
  return json;
}

async function confirmarVendaLojaMP(opts) {
  opts = opts || {};
  var headers = { 'Content-Type': 'application/json' };
  if (typeof supabaseKey === 'string' && supabaseKey) {
    headers['Authorization'] = 'Bearer ' + supabaseKey;
    headers['apikey'] = supabaseKey;
  }
  var res = await fetch(LOJA_CONFIRMAR_URL, {
    method: 'POST',
    headers: headers,
    body: JSON.stringify(opts)
  });
  var json = await res.json().catch(function() { return {}; });
  if (!res.ok) throw new Error(json.error || json.message || ('HTTP ' + res.status));
  return json;
}

function atualizarUIStatusLojaPix(html) {
  var el = document.getElementById('lojaPixStatusTxt');
  if (el) el.innerHTML = html;
}

function iniciarPollLojaPix(opts) {
  opts = opts || {};
  pararPollLojaPix();
  var tentativas = 0;
  var maxTentativas = opts.maxTentativas || 60;
  var intervalMs = opts.intervalMs || 3000;

  async function tick() {
    tentativas++;
    var pend = carregarLojaVendaPendente();
    if (!pend) { pararPollLojaPix(); return; }

    atualizarUIStatusLojaPix(
      'Aguardando confirmação do PIX no Mercado Pago...<br>'
      + '<span style="color:#94a3b8;font-size:12px;">(' + tentativas + '/' + maxTentativas + ')</span>'
    );

    try {
      // Sempre consulta via edge da oficina (token do dono) — NÃO usa token da plataforma
      var conf = await confirmarVendaLojaMP({
        office_id: pend.office_id,
        id_venda: pend.id_venda,
        external_reference: pend.external_reference || pend.txid || pend.mp_external_ref
      });
      if (conf && conf.ok) {
        pararPollLojaPix();
        atualizarUIStatusLojaPix('✅ <b style="color:#22c55e;">Pagamento aprovado!</b><br>A oficina já recebeu a confirmação da venda.');
        limparLojaVendaPendente();
        if (typeof mostrarToast === 'function') mostrarToast('Pagamento confirmado!', 'sucesso');
        var btn = document.getElementById('btnLojaAbrirMp');
        if (btn) btn.style.display = 'none';
        var btnJa = document.getElementById('btnLojaJaPaguei');
        if (btnJa) btnJa.style.display = 'none';
        return;
      }
      if (conf && conf.status && conf.status !== 'pending' && conf.status !== 'in_process') {
        // status conhecido mas não approved (rejected etc.)
        console.log('[loja poll] status MP:', conf.status);
      }
    } catch (e) {
      console.warn('[loja poll]', e);
    }

    if (tentativas >= maxTentativas) {
      pararPollLojaPix();
      atualizarUIStatusLojaPix(
        'Ainda não confirmamos automaticamente.<br>'
        + 'Se você já pagou, a oficina pode confirmar em Vendas. Ou toque em "Já paguei".'
      );
      var btnJa = document.getElementById('btnLojaJaPaguei');
      if (btnJa) btnJa.style.display = 'block';
    }
  }

  tick();
  __lojaPollTimer = setInterval(tick, intervalMs);
}

/**
 * Fluxo principal: registra venda + cria preferência MP + inicia poll
 * Substitui o PIX estático como caminho preferencial.
 */
async function gerarPixSimplesERegistrar() {
  // IDs do modal dinâmico da vitrine: vendaNome / vendaTel / vendaQtd
  // IDs legados: vendaNomeCliente, compraNomeCliente, etc.
  var inputNome = document.getElementById('vendaNome')
    || document.getElementById('vendaNomeCliente')
    || document.getElementById('compraNomeCliente');
  var inputTel = document.getElementById('vendaTel')
    || document.getElementById('vendaTelCliente')
    || document.getElementById('compraTelCliente');
  var inputQtd = document.getElementById('vendaQtd')
    || document.getElementById('compraQtd');
  if (!inputNome || !inputTel) {
    console.warn('[loja] campos nome/tel não encontrados no DOM');
    alert('Erro no formulário de compra. Feche e abra de novo.');
    return;
  }
  var nomeCliente = (inputNome.value || '').trim();
  var telCliente = (inputTel.value || '').trim();
  var qtd = parseInt(inputQtd && inputQtd.value, 10) || 1;
  if (!nomeCliente || !telCliente) {
    alert('Informe nome e WhatsApp.');
    if (!nomeCliente && inputNome.focus) inputNome.focus();
    else if (inputTel.focus) inputTel.focus();
    return;
  }

  var idDono = null;
  if (typeof obterIdLojaAtual === 'function') idDono = obterIdLojaAtual();
  if (!idDono && typeof idOficinaDaLojaAtual !== 'undefined') idDono = idOficinaDaLojaAtual;
  if (!idDono && typeof usuarioAtualId !== 'undefined') idDono = usuarioAtualId;
  if (!idDono) {
    alert('Oficina não identificada. Abra a vitrine pelo link correto.');
    return;
  }
  if (typeof precoUnitarioSelecionado === 'undefined' || !produtoSelecionadoParaCompra) {
    alert('Produto não selecionado.');
    return;
  }
  if (qtd < 1) qtd = 1;
  if (typeof estoqueDisponivelSelecionado === 'number' && qtd > estoqueDisponivelSelecionado) {
    qtd = estoqueDisponivelSelecionado;
  }
  var total = qtd * precoUnitarioSelecionado;
  if (!(total > 0)) {
    alert('Valor inválido.');
    return;
  }

  var idVenda = 'VD' + Date.now();
  var externalRef = ('LOJA-' + idVenda).substring(0, 64);
  var btnGerar = document.querySelector('#etapaDadosCompra button, button[onclick*="gerarPixSimplesERegistrar"]');

  try {
    if (btnGerar) { btnGerar.disabled = true; btnGerar.textContent = 'Gerando pagamento...'; }

    // 1) registra venda aguardando
    var { data: dadosAtuais, error: erroBusca } = await supabaseClient
      .from('user_data')
      .select('historico')
      .eq('user_id', idDono)
      .single();
    if (erroBusca) throw new Error('Erro ao conectar na oficina.');

    var hist = Array.isArray(dadosAtuais.historico) ? dadosAtuais.historico : [];
    hist.unshift({
      id_venda: idVenda,
      data: new Date().toLocaleDateString('pt-BR'),
      status: 'Aguardando PIX',
      tipo_registro: 'VENDA_DIRETA_BALCAO',
      pagamento: 'PIX Mercado Pago',
      pix_txid: externalRef,
      mp_external_ref: externalRef,
      cliente: { nome: nomeCliente, tel: telCliente, endereco: 'Vitrine Virtual' },
      veiculo: { modelo: 'Balcão / Vitrine', placa: '---' },
      produto_nome: typeof nomeProdutoSelecionado !== 'undefined' ? nomeProdutoSelecionado : 'Produto',
      produto_id: produtoSelecionadoParaCompra,
      quantidade: qtd,
      valor_unitario: precoUnitarioSelecionado,
      total_pago: total,
      lucro: total
    });

    var { error: erroUp } = await supabaseClient
      .from('user_data')
      .update({ historico: hist, updated_at: new Date().toISOString() })
      .eq('user_id', idDono);
    if (erroUp) throw erroUp;

    // 2) tenta preferência MP da OFICINA (dinheiro na conta dela)
    var pref = await criarPreferenciaLojaMP({
      valor: total,
      titulo: (typeof nomeProdutoSelecionado !== 'undefined' ? nomeProdutoSelecionado : 'Produto') + ' x' + qtd,
      office_id: idDono,
      id_venda: idVenda,
      external_reference: externalRef,
      nome: nomeCliente,
      email: (telCliente.replace(/\D/g, '') || 'cliente') + '@cliente.aldineicar.app',
      success_url: window.location.origin + window.location.pathname
        + (window.location.search || '?') + (window.location.search ? '&' : '')
        + 'loja_pago=1&ref=' + encodeURIComponent(externalRef)
        + '&office=' + encodeURIComponent(idDono)
        + '&venda=' + encodeURIComponent(idVenda)
    });

    // Sem MP da oficina → PIX manual (chave da oficina)
    if (pref && (pref.modo === 'manual' || pref.error === 'oficina_sem_mp')) {
      await gerarPixManualOficinaFallback({
        idDono: idDono,
        idVenda: idVenda,
        externalRef: externalRef,
        total: total,
        nomeCliente: nomeCliente,
        telCliente: telCliente,
        qtd: qtd
      });
      return;
    }

    var initPoint = pref.init_point || pref.sandbox_init_point;
    if (!initPoint) throw new Error(pref.error || pref.message || 'Link de pagamento não retornado');
    console.log('[loja] cobrança collector=', pref.collector || 'oficina', 'mp_user_id=', pref.mp_user_id || '(oauth)');

    salvarLojaVendaPendente({
      office_id: idDono,
      id_venda: idVenda,
      external_reference: externalRef,
      preference_id: pref.preference_id || pref.id,
      valor: total,
      init_point: initPoint
    });

    // 3) UI etapa pagamento
    var etapaDados = document.getElementById('etapaDadosCompra');
    var etapaPix = document.getElementById('etapaPixCompra');
    if (etapaDados) etapaDados.style.display = 'none';
    if (etapaPix) {
      etapaPix.style.display = 'block';
      // injeta status + botões MP se não existirem
      if (!document.getElementById('lojaPixStatusTxt')) {
        var box = document.createElement('div');
        box.id = 'lojaPixAutoBox';
        box.style.cssText = 'margin:12px 0;padding:14px;background:#111;border:1px solid #333;border-radius:12px;text-align:center;';
        box.innerHTML =
          '<p id="lojaPixStatusTxt" style="margin:0 0 12px;color:#e4e4e7;font-size:13px;font-weight:600;line-height:1.4;">Redirecionando ao Mercado Pago...</p>'
          + '<a id="btnLojaAbrirMp" href="' + initPoint + '" target="_blank" rel="noopener" '
          + 'style="display:inline-block;width:100%;box-sizing:border-box;padding:14px;background:#22c55e;color:#fff;border:none;border-radius:10px;font-weight:800;text-decoration:none;margin-bottom:8px;">💳 Pagar com PIX (Mercado Pago)</a>'
          + '<button type="button" id="btnLojaJaPaguei" style="display:none;width:100%;padding:12px;background:#2563eb;color:#fff;border:none;border-radius:10px;font-weight:700;cursor:pointer;">✓ Já paguei — verificar</button>';
        etapaPix.insertBefore(box, etapaPix.firstChild);
        document.getElementById('btnLojaJaPaguei').onclick = function() {
          verificarLojaJaPaguei();
        };
      } else {
        var a = document.getElementById('btnLojaAbrirMp');
        if (a) a.href = initPoint;
      }
    }

    var vg = document.getElementById('pixValorGrande');
    if (vg) vg.innerText = 'R$ ' + total.toFixed(2);
    var pid = document.getElementById('pixPedidoId');
    if (pid) pid.innerText = 'Pedido: ' + idVenda;

    // esconde PIX estático antigo se preferir só MP
    var qr = document.getElementById('pixQrBox');
    var copia = document.getElementById('pixCopiaCola');
    if (qr) qr.innerHTML = '<p style="color:#94a3b8;font-size:12px;">Use o botão verde para pagar com PIX no Mercado Pago.<br>A confirmação é automática.</p>';
    if (copia) copia.style.display = 'none';

    iniciarPollLojaPix();

    // abre MP em nova aba
    try { window.open(initPoint, '_blank'); } catch (e2) {}

  } catch (err) {
    console.error(err);
    alert('Erro ao gerar pagamento: ' + (err.message || err));
  } finally {
    if (btnGerar) { btnGerar.disabled = false; btnGerar.textContent = 'Gerar PIX →'; }
  }
}

async function verificarLojaJaPaguei() {
  var pend = carregarLojaVendaPendente();
  if (!pend) {
    alert('Pedido não encontrado nesta sessão.');
    return;
  }
  try {
    atualizarUIStatusLojaPix('Verificando pagamento...');
    var conf = await confirmarVendaLojaMP({
      office_id: pend.office_id,
      id_venda: pend.id_venda,
      external_reference: pend.external_reference
    });
    if (conf.ok) {
      pararPollLojaPix();
      atualizarUIStatusLojaPix('✅ <b style="color:#22c55e;">Pagamento confirmado!</b>');
      limparLojaVendaPendente();
      alert('Pagamento confirmado! Obrigado.');
    } else {
      atualizarUIStatusLojaPix('Ainda pendente (' + (conf.status || 'aguardando') + '). Se acabou de pagar, aguarde alguns segundos.');
    }
  } catch (e) {
    alert('Erro: ' + (e.message || e));
  }
}

async function processarRetornoLojaPago() {
  try {
    var params = new URLSearchParams(window.location.search || '');
    if (params.get('loja_pago') !== '1' && params.get('loja_pago') !== 'pendente') return;
    var ref = params.get('ref') || '';
    var office = params.get('office') || '';
    var venda = params.get('venda') || '';
    var paymentId = params.get('payment_id') || params.get('collection_id') || '';
    var pend = carregarLojaVendaPendente() || {};
    if (!office) office = pend.office_id;
    if (!venda) venda = pend.id_venda;
    if (!ref) ref = pend.external_reference;
    if (!office) return;

    var conf = await confirmarVendaLojaMP({
      office_id: office,
      id_venda: venda,
      external_reference: ref,
      payment_id: paymentId
    });
    if (conf && conf.ok) {
      limparLojaVendaPendente();
      alert('Pagamento da loja confirmado! Obrigado pela compra.');
    }
    try {
      var u = new URL(window.location.href);
      ['loja_pago','ref','office','venda','payment_id','collection_id','status','preference_id'].forEach(function(k) {
        u.searchParams.delete(k);
      });
      window.history.replaceState({}, '', u.pathname + (u.search || ''));
    } catch (e2) {}
  } catch (e) {
    console.warn('retorno loja', e);
  }
}

