async function confirmarPagamentoVenda(idxHist) {
 if (idxHist < 0 || idxHist >= historico.length) {
 if (typeof mostrarToast === 'function') mostrarToast('Venda não encontrada.', 'erro');
 return;
 }
 const venda = historico[idxHist];
 if ((venda.status || '') === 'Pago PIX') {
 if (typeof mostrarToast === 'function') mostrarToast('Esta venda já está paga.', 'aviso');
 return;
 }
 const total = parseFloat(venda.total_pago || 0) || 0;
 const nomeCli = (venda.cliente && venda.cliente.nome) || '';
 const ok = confirm('Confirmar recebimento de R$ ' + total.toFixed(2) + '?\n\nCliente: ' + nomeCli + '\nProduto: ' + (venda.produto_nome || ''));
 if (!ok) return;

 venda.status = 'Pago PIX';
 venda.pagamento = 'PIX';
 venda.confirmado_em = new Date().toISOString();
 venda.confirmado_por = 'oficina';

 if (venda.produto_id) {
 try {
 const { data: prod } = await supabaseClient
 .from('produtos_loja')
 .select('estoque')
 .eq('id', venda.produto_id)
 .maybeSingle();
 if (prod) {
 const novo = Math.max(0, (parseInt(prod.estoque) || 0) - (parseInt(venda.quantidade) || 1));
 await supabaseClient.from('produtos_loja').update({ estoque: novo }).eq('id', venda.produto_id);
 }
 } catch (e) { console.warn(e); }
 }

 await salvarNoBanco();
 renderizarListaVendasExclusiva();
 if (typeof renderDashboard === 'function') {
 const dash = document.getElementById('aba-dashboard');
 if (dash && dash.style.display !== 'none') renderDashboard();
 }
 if (typeof mostrarToast === 'function') mostrarToast('Pagamento confirmado!', 'sucesso');
}


/**
 * Verifica vendas "Aguardando PIX" no MP da oficina e marca como Pago PIX.
 * Retorna true se alguma venda foi atualizada.
 */
async function confirmarPendentesLojaPix(officeId, histArr) {
  if (!officeId || !Array.isArray(histArr)) return false;
  var pendentes = [];
  for (var i = 0; i < histArr.length; i++) {
    var h = histArr[i];
    if (!h) continue;
    var st = String(h.status || '');
    if (st.indexOf('Aguardando') < 0) continue;
    var isVenda = h.tipo_registro === 'VENDA_DIRETA_BALCAO' ||
      h.tipo_registro === 'LOJA_VIRTUAL' ||
      (h.pagamento && String(h.pagamento).indexOf('Mercado Pago') >= 0) ||
      h.mp_external_ref || h.pix_txid;
    if (!isVenda) continue;
    pendentes.push({ idx: i, item: h });
  }
  if (!pendentes.length) return false;
  if (typeof confirmarVendaLojaMP !== 'function') return false;

  var alguma = false;
  // limita a 5 por abertura de aba para não sobrecarregar
  var max = Math.min(pendentes.length, 5);
  for (var j = 0; j < max; j++) {
    var p = pendentes[j];
    var ref = p.item.mp_external_ref || p.item.pix_txid || '';
    if (!ref && !p.item.id_venda) continue;
    try {
      var conf = await confirmarVendaLojaMP({
        office_id: officeId,
        id_venda: p.item.id_venda || '',
        external_reference: ref
      });
      if (conf && conf.ok) {
        alguma = true;
        // atualiza array local (edge já salvou no banco)
        histArr[p.idx].status = 'Pago PIX';
        histArr[p.idx].pagamento = 'PIX Mercado Pago';
        histArr[p.idx].mp_payment_id = conf.payment_id || histArr[p.idx].mp_payment_id;
        histArr[p.idx].pago_em = new Date().toISOString();
        histArr[p.idx].confirmacao = 'automatica_mp_oficina';
      }
    } catch (e) {
      console.warn('[confirmar pendente]', e);
    }
  }
  if (alguma) {
    historico = histArr;
    if (typeof mostrarToast === 'function') {
      mostrarToast('Venda(s) PIX confirmada(s) automaticamente!', 'sucesso');
    }
  }
  return alguma;
}

window.confirmarPendentesLojaPix = confirmarPendentesLojaPix;

/** Poll em background no painel do DONO: confirma PIX pendentes a cada 20s */
var __lojaDonoPollTimer = null;
function pararMonitorPendentesLojaDono() {
  if (__lojaDonoPollTimer) { clearInterval(__lojaDonoPollTimer); __lojaDonoPollTimer = null; }
}
async function tickMonitorPendentesLojaDono() {
  try {
    if (!usuarioAtualId || !navigator.onLine) return;
    // só se houver MP conectado
    if (!dadosOficina || !(dadosOficina.mp_access_token || dadosOficina.mp_loja_ativo)) return;
    var lista = Array.isArray(historico) ? historico : [];
    var pend = lista.filter(function(h) {
      if (!h) return false;
      var st = String(h.status || '');
      if (st !== 'Aguardando PIX' && st.indexOf('Aguardando') < 0) return false;
      var isVenda = h.tipo_registro === 'VENDA_DIRETA_BALCAO' || h.tipo_registro === 'LOJA_VIRTUAL'
        || (h.pagamento && String(h.pagamento).indexOf('PIX') >= 0);
      return isVenda;
    });
    if (!pend.length) return;
    var mudou = await confirmarPendentesLojaPix(usuarioAtualId, lista);
    if (mudou) {
      // recarrega historico do banco
      try {
        var { data } = await supabaseClient.from('user_data').select('historico').eq('user_id', usuarioAtualId).single();
        if (data && Array.isArray(data.historico)) historico = data.historico;
      } catch (e2) {}
      if (typeof renderizarListaVendasExclusiva === 'function') {
        var vd = document.getElementById('aba-vendas');
        if (vd && vd.style.display !== 'none') renderizarListaVendasExclusiva();
      }
      if (typeof renderDashboard === 'function') {
        var dash = document.getElementById('aba-dashboard');
        if (dash && dash.style.display !== 'none') renderDashboard();
      }
      if (typeof mostrarToast === 'function') mostrarToast('Venda PIX confirmada automaticamente!', 'sucesso');
      try {
        if (typeof dispararNotificacaoBrowser === 'function') {
          dispararNotificacaoBrowser('ALDINEICAR', 'Pagamento PIX da loja confirmado!');
        }
      } catch (e3) {}
    }
  } catch (e) { console.warn('[loja dono poll]', e); }
}
function iniciarMonitorPendentesLojaDono() {
  pararMonitorPendentesLojaDono();
  if (!usuarioAtualId) return;
  // primeira checagem em 5s, depois a cada 20s
  setTimeout(tickMonitorPendentesLojaDono, 5000);
  __lojaDonoPollTimer = setInterval(tickMonitorPendentesLojaDono, 20000);
}
window.iniciarMonitorPendentesLojaDono = iniciarMonitorPendentesLojaDono;
window.pararMonitorPendentesLojaDono = pararMonitorPendentesLojaDono;


async function renderizarListaVendasExclusiva() {
 const corpoTabela = document.getElementById('tabela-vendas-corpo');
 if (!corpoTabela) {
 console.error("Erro: tabela-vendas-corpo não encontrado.");
 return;
 }

 corpoTabela.innerHTML = `<tr><td colspan="8" style="text-align:center; padding:20px; color:#64748b;">🔄 Carregando vendas...</td></tr>`;

 try {
 let historicoGeral = Array.isArray(historico) ? historico : [];

 try {
 const { data: { session } } = await supabaseClient.auth.getSession();
 const idUsuarioLogado = session?.user?.id || usuarioAtualId;
 if (idUsuarioLogado) {
 const { data: dados, error } = await supabaseClient
 .from('user_data')
 .select('historico')
 .eq('user_id', idUsuarioLogado)
 .single();
 if (!error && dados && Array.isArray(dados.historico)) {
 historicoGeral = dados.historico;
 historico = dados.historico;
 }
 // Auto-confirma vendas "Aguardando PIX" via token da oficina (edge)
 try {
 if (typeof confirmarPendentesLojaPix === 'function') {
 var mudou = await confirmarPendentesLojaPix(idUsuarioLogado, historicoGeral);
 if (mudou) {
 historicoGeral = historico;
 }
 }
 } catch (eAuto) { console.warn('[vendas auto-pix]', eAuto); }
 }
 } catch (e) {
 console.warn('Usando histórico local para vendas:', e);
 }

 const vendasComIdx = [];
 historicoGeral.forEach((item, idxHist) => {
 const isVenda = item.tipo_registro === 'VENDA_DIRETA_BALCAO' ||
 item.tipo_registro === 'LOJA_VIRTUAL' ||
 item.tipo_servico === '[VENDA DIRETA]' ||
 (item.veiculo && item.veiculo.tipo_servico && String(item.veiculo.tipo_servico).includes('[VENDA DIRETA]'));
 if (isVenda) vendasComIdx.push({ item, idxHist });
 });

 if (vendasComIdx.length === 0) {
 corpoTabela.innerHTML = `<tr><td colspan="8" style="text-align:center; padding:24px; color:#94a3b8;">Nenhuma venda encontrada.</td></tr>`;
 return;
 }

 let linhasHTML = '';
 vendasComIdx.forEach(({ item: venda, idxHist }) => {
 let nomeCliente = 'Cliente';
 if (venda.cliente) {
 if (typeof venda.cliente === 'object' && venda.cliente.nome) nomeCliente = venda.cliente.nome;
 else if (typeof venda.cliente === 'string') nomeCliente = venda.cliente;
 } else if (venda.cliente_nome) {
 nomeCliente = venda.cliente_nome;
 }

 const nomeProduto = venda.produto_nome || venda.nome_produto || 'Produto';
 const quantidadeItem = venda.quantidade || 1;

 let valorTotalRaw = venda.total_pago || venda.valor_total || venda.totalCobrado || 0;
 if (typeof valorTotalRaw === 'string') {
 valorTotalRaw = parseFloat(valorTotalRaw.replace('R$', '').replace(/\./g, '').replace(',', '.').trim()) || 0;
 }
 const valorTotal = parseFloat(valorTotalRaw) || 0;
 const statusVenda = venda.status || 'Concluído';
 const idVenda = venda.id_venda || ('#' + idxHist);

 const aguardando = String(statusVenda).toLowerCase().includes('aguardando');
 const badgeBg = aguardando ? '#fef3c7' : (String(statusVenda).toLowerCase().includes('pago') ? '#ecfdf5' : '#f1f5f9');
 const badgeFg = aguardando ? '#b45309' : (String(statusVenda).toLowerCase().includes('pago') ? '#059669' : '#475569');
 let acoes = '';
 if (aguardando) {
 acoes += `<button onclick="confirmarPagamentoVenda(${idxHist})" title="Confirmar que o PIX caiu na conta" style="background:#22c55e;color:#fff;border:none;padding:6px 10px;border-radius:6px;cursor:pointer;font-size:12px;font-weight:700;margin-right:4px;">✓ Recebi</button>`;
 }
 acoes += `<button onclick="deletarVendaPorIndice(${idxHist})" title="Excluir" style="background:#fee2e2;color:#dc2626;border:none;padding:6px 10px;border-radius:6px;cursor:pointer;font-size:14px;">🗑️</button>`;

 linhasHTML += `
 <tr>
 <td style="color:#64748b;">${idVenda}</td>
 <td>${venda.data || ''}</td>
 <td>${nomeCliente}</td>
 <td style="color:#059669; font-weight:600;">${nomeProduto}</td>
 <td>${quantidadeItem}</td>
 <td style="font-weight:700;">R$ ${valorTotal.toFixed(2)}</td>
 <td><span style="background:${badgeBg};color:${badgeFg};padding:4px 8px;border-radius:6px;font-size:12px;font-weight:600;">${statusVenda}</span></td>
 <td style="white-space:nowrap;">${acoes}</td>
 </tr>`;
 });

 corpoTabela.innerHTML = linhasHTML;
 } catch (err) {
 console.error("Erro na listagem das vendas:", err);
 corpoTabela.innerHTML = `<tr><td colspan="8" style="text-align:center; padding:20px; color:#ef4444;">Erro: ${err.message}</td></tr>`;
 }
}

