/** Envia e-mail de recuperação */
async function recuperarSenha() {
  var emailEl = document.getElementById('recuperarEmail') || document.getElementById('loginEmail');
  var email = (emailEl && emailEl.value || '').trim();
  if (!email) {
    alert('Digite seu e-mail para recuperar a conta.');
    return;
  }
  var btn = document.getElementById('btnEnviarRecuperacao');
  if (btn) { btn.disabled = true; btn.textContent = 'Enviando...'; }
  try {
    var redirectTo = window.location.origin + window.location.pathname.replace(/\/$/, '/') ;
    if (redirectTo.indexOf('index.html') < 0 && window.location.pathname.indexOf('index.html') >= 0) {
      redirectTo = window.location.origin + window.location.pathname;
    }
    // URL limpa + flag
    redirectTo = window.location.origin + (window.location.pathname || '/') ;
    if (redirectTo.slice(-1) === '/' && redirectTo !== window.location.origin + '/') {
      /* ok */
    }
    // URL fixa do site (deve estar em Redirect URLs no Supabase)
    redirectTo = 'https://aldineicar.vercel.app/';
    try {
      if (window.location && window.location.origin && window.location.origin.indexOf('localhost') < 0) {
        redirectTo = window.location.origin + '/';
      }
    } catch (eR) {}
    redirectTo = redirectTo + '?recuperar=1';

    var res = await supabaseClient.auth.resetPasswordForEmail(email, { redirectTo: redirectTo });
    if (res.error) throw res.error;
    alert('Enviamos um link para ' + email + '.\n\nAbra o e-mail, clique no link e defina a nova senha nesta tela.');
    var ok = document.getElementById('esqueciSenhaMsg');
    if (ok) {
      ok.style.display = 'block';
      ok.textContent = 'E-mail enviado! Verifique sua caixa de entrada (e o spam).';
    }
  } catch (e) {
    console.error(e);
    alert('Não foi possível enviar o e-mail: ' + (e.message || e));
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Enviar link de recuperação'; }
  }
}

/** Processa token/código do link do e-mail e abre sessão de recovery */
function lerErroAuthNaUrl() {
  try {
    var url = new URL(window.location.href);
    var err = url.searchParams.get('error') || url.searchParams.get('error_code');
    var desc = url.searchParams.get('error_description') || '';
    var hash = window.location.hash || '';
    if ((!err || err === '') && hash) {
      var hp = new URLSearchParams(hash.replace(/^#/, ''));
      err = hp.get('error') || hp.get('error_code') || err;
      desc = hp.get('error_description') || desc;
    }
    if (desc) {
      try { desc = decodeURIComponent(desc.replace(/\+/g, ' ')); } catch (e) {}
    }
    return { error: err, description: desc };
  } catch (e2) {
    return { error: null, description: '' };
  }
}

async function processarLinkRecuperacao() {
  if (!supabaseClient || !supabaseClient.auth) return false;
  try {
    window.__pendenteRecuperacaoSenha = true;
    var url = new URL(window.location.href);
    var code = url.searchParams.get('code');
    var token_hash = url.searchParams.get('token_hash');
    var type = url.searchParams.get('type');
    var recuperar = url.searchParams.get('recuperar');
    var hash = window.location.hash || '';

    // Erro já veio na URL (link expirado / usado)
    var er = lerErroAuthNaUrl();
    if (er.error) {
      console.warn('[recuperar] erro na URL', er);
      return false;
    }

    // PKCE (se ainda vier code)
    if (code) {
      var ex = await supabaseClient.auth.exchangeCodeForSession(window.location.href);
      if (!ex.error) return true;
      console.warn('[recuperar] exchangeCode', ex.error);
    }

    // token_hash
    if (token_hash && (type === 'recovery' || type === 'email' || !type)) {
      var vo = await supabaseClient.auth.verifyOtp({
        token_hash: token_hash,
        type: 'recovery'
      });
      if (!vo.error) return true;
      console.warn('[recuperar] verifyOtp', vo.error);
    }

    // Hash implícito: #access_token=...&type=recovery
    if (hash.indexOf('access_token') >= 0) {
      var hp = new URLSearchParams(hash.replace(/^#/, ''));
      var access_token = hp.get('access_token');
      var refresh_token = hp.get('refresh_token');
      if (access_token) {
        var ss = await supabaseClient.auth.setSession({
          access_token: access_token,
          refresh_token: refresh_token || ''
        });
        if (!ss.error) return true;
        console.warn('[recuperar] setSession', ss.error);
      }
      await new Promise(function(r) { setTimeout(r, 500); });
      var sess = await supabaseClient.auth.getSession();
      if (sess && sess.data && sess.data.session) return true;
    }

    if (recuperar === '1') {
      var s2 = await supabaseClient.auth.getSession();
      if (s2 && s2.data && s2.data.session) return true;
    }

    return false;
  } catch (e) {
    console.warn('[recuperar] processarLink', e);
    return false;
  }
}

async function salvarNovaSenhaRecuperacao() {
  var p1 = (document.getElementById('novaSenhaRec') && document.getElementById('novaSenhaRec').value) || '';
  var p2 = (document.getElementById('novaSenhaRec2') && document.getElementById('novaSenhaRec2').value) || '';
  if (!p1 || p1.length < 6) { alert('Senha mínima: 6 caracteres.'); return; }
  if (p1 !== p2) { alert('As senhas não coincidem.'); return; }

  var btn = document.getElementById('btnSalvarNovaSenha');
  if (btn) { btn.disabled = true; btn.textContent = 'Salvando...'; }

  try {
    // Garante sessão de recovery
    var sess = await supabaseClient.auth.getSession();
    if (!sess || !sess.data || !sess.data.session) {
      var ok = await processarLinkRecuperacao();
      if (!ok) {
        sess = await supabaseClient.auth.getSession();
      } else {
        sess = await supabaseClient.auth.getSession();
      }
    }
    if (!sess || !sess.data || !sess.data.session) {
      throw new Error('Sessão de recuperação não encontrada. Abra o link do e-mail novamente (o link expira e só funciona uma vez).');
    }

    var res = await supabaseClient.auth.updateUser({ password: p1 });
    if (res.error) throw res.error;

    alert('Senha atualizada com sucesso! Você já pode entrar.');
    window.__pendenteRecuperacaoSenha = false;
    try {
      var u = new URL(window.location.href);
      u.searchParams.delete('recuperar');
      u.searchParams.delete('code');
      u.searchParams.delete('type');
      u.searchParams.delete('token_hash');
      window.history.replaceState({}, '', u.pathname);
      if (window.location.hash) {
        window.history.replaceState({}, '', u.pathname);
      }
    } catch (e2) {}

    // opcional: signOut para forçar login limpo com nova senha
    try { await supabaseClient.auth.signOut(); } catch (e3) {}
    voltarParaLogin();
  } catch (e) {
    console.error(e);
    alert('Erro ao salvar senha: ' + (e.message || e));
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Salvar nova senha'; }
  }
}

