async function carregarPainelAdmin() {
  var box = document.getElementById('admin-oficinas-lista');
  if (!box) return;
  box.innerHTML = '<p style="color:#94a3b8;padding:12px;">Carregando oficinas...</p>';
  try {
    var sessionRes = await supabaseClient.auth.getSession();
    var token = sessionRes && sessionRes.data && sessionRes.data.session && sessionRes.data.session.access_token;
    if (!token) throw new Error('Faça login novamente');
    var headers = {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + token,
      'apikey': (typeof supabaseKey === 'string' ? supabaseKey : '')
    };
    var res = await fetch(ADMIN_LISTAR_URL, { method: 'POST', headers: headers, body: '{}' });
    var json = await res.json().catch(function() { return {}; });
    if (!res.ok) throw new Error(json.error || ('HTTP ' + res.status));

    window.__adminOficinasCache = json.oficinas || [];
    var lista = window.__adminOficinasCache.slice();
    var manut = !!json.manutencao;

    var topo = document.getElementById('admin-topo-controles');
    if (topo) {
      topo.innerHTML =
        '<div class="admin-kpis">'
        + '<div class="admin-kpi"><span>Contas</span><strong>' + (json.total_auth || lista.length) + '</strong></div>'
        + '<div class="admin-kpi"><span>Pagas</span><strong>' + (json.total_pagas || 0) + '</strong></div>'
        + '<div class="admin-kpi"><span>Bloqueadas</span><strong>' + (json.total_bloqueadas || 0) + '</strong></div>'
        + '<div class="admin-kpi' + (manut ? ' admin-kpi-warn' : '') + '"><span>Manutenção</span><strong>' + (manut ? 'ON' : 'OFF') + '</strong></div>'
        + '</div>'
        + '<div class="admin-manutencao-box">'
        + '<label class="admin-switch-label"><input type="checkbox" id="adminManutencaoToggle" ' + (manut ? 'checked' : '') + ' onchange="adminToggleManutencao(this.checked)"> Modo manutenção (bloqueia login de todos, exceto admin)</label>'
        + '<input type="text" id="adminManutencaoMsg" value="' + String(json.mensagem_manutencao || 'Sistema em manutenção. Voltamos em breve.').replace(/"/g, '&quot;') + '" placeholder="Mensagem exibida no login" class="admin-input-msg">'
        + '</div>'
        + '<div class="admin-toolbar">'
        + '<input type="search" id="adminBusca" placeholder="Buscar e-mail, nome, telefone..." oninput="adminFiltrarLista()" class="admin-input-busca">'
        + '<select id="adminFiltro" onchange="adminFiltrarLista()" class="admin-select">'
        + '<option value="todas">Todas</option>'
        + '<option value="ativas">Ativas</option>'
        + '<option value="bloqueadas">Bloqueadas</option>'
        + '<option value="pagas">Taxa paga</option>'
        + '<option value="nao_pagas">Taxa não paga</option>'
        + '</select>'
        + '<button type="button" class="btn-page-action" onclick="adminExportarCSV()">Exportar CSV</button>'
        + '</div>';
    }

    adminRenderLista(lista);
    // Storage usage box
    var stHost = document.getElementById('admin-storage-box');
    if (!stHost) {
      var topoEl = document.getElementById('admin-topo-controles');
      if (topoEl) {
        stHost = document.createElement('div');
        stHost.id = 'admin-storage-box';
        stHost.className = 'admin-storage-box';
        topoEl.appendChild(stHost);
      }
    }
    if (typeof carregarStorageAdmin === 'function') carregarStorageAdmin();
  } catch (e) {
    console.error(e);
    box.innerHTML = '<p style="color:#dc2626;padding:12px;">Erro admin: ' + (e.message || e) + '</p>';
  }
}

function adminRenderLista(lista) {
  var box = document.getElementById('admin-oficinas-lista');
  if (!box) return;
  if (!lista.length) {
    box.innerHTML = '<p style="padding:12px;color:#64748b;">Nenhuma conta neste filtro.</p>';
    return;
  }
  box.innerHTML = lista.map(function(o) {
    var bloq = !!o.bloqueada;
    var paga = !!o.taxa_paga;
    var idEsc = String(o.user_id || '').replace(/'/g, "\\'");
    var emailEsc = String(o.email || '').replace(/'/g, "\\'");
    var notaEsc = String(o.admin_nota || '').replace(/"/g, '&quot;');
    var badge = bloq
      ? '<span class="admin-badge admin-badge-off">Bloqueada</span>'
      : '<span class="admin-badge admin-badge-on">Ativa</span>';
    var badgePg = paga
      ? '<span class="admin-badge admin-badge-on">Taxa paga</span>'
      : '<span class="admin-badge admin-badge-off">Taxa pendente</span>';
    var btnBloq = bloq
      ? '<button type="button" class="admin-btn-ok" onclick="adminAcaoConta(\'' + idEsc + '\',\'desbloquear\')">Desbloquear</button>'
      : '<button type="button" class="admin-btn-danger" onclick="adminAcaoConta(\'' + idEsc + '\',\'bloquear\')">Bloquear</button>';
    var btnPg = paga
      ? '<button type="button" class="admin-btn-sec" onclick="adminAcaoConta(\'' + idEsc + '\',\'marcar_nao_pago\')">Marcar não pago</button>'
      : '<button type="button" class="admin-btn-ok" onclick="adminAcaoConta(\'' + idEsc + '\',\'marcar_pago\')">Marcar pago</button>';
    var wa = o.whatsapp
      ? '<a class="admin-btn-sec" href="https://wa.me/55' + o.whatsapp + '" target="_blank" rel="noopener">WhatsApp</a>'
      : '';
    var vit = o.vitrine_url
      ? '<a class="admin-btn-sec" href="' + o.vitrine_url + '" target="_blank" rel="noopener">Vitrine</a>'
      : '';
    return '<div class="admin-oficina-card' + (bloq ? ' admin-oficina-bloqueada' : '') + '">'
      + '<div class="admin-oficina-head"><strong>' + (o.nome || '—') + '</strong><span>' + badge + ' ' + badgePg + '</span></div>'
      + '<div class="admin-oficina-meta">' + (o.email || 'sem e-mail') + '</div>'
      + '<div class="admin-oficina-meta">' + (o.fone || '') + (o.profissao ? ' · ' + o.profissao : '') + '</div>'
      + '<div class="admin-oficina-meta">Vencimento plano: ' + (o.assinatura_proximo_vencimento ? formatarDataBRISO(o.assinatura_proximo_vencimento) : '—') + ' · ' + (o.assinatura_status || '') + '</div>'
      + '<div class="admin-oficina-meta">OS/Hist: ' + (o.qtd_historico || 0) + ' · Clientes: ' + (o.qtd_clientes || 0) + '</div>'
      + '<div class="admin-oficina-meta" style="font-size:11px;">ID: ' + (o.user_id || '') + '</div>'
      + '<div class="admin-nota-row"><input type="text" class="admin-input-nota" id="nota-' + idEsc + '" value="' + notaEsc + '" placeholder="Nota interna de suporte...">'
      + '<button type="button" class="admin-btn-sec" onclick="adminSalvarNota(\'' + idEsc + '\')">Salvar nota</button></div>'
      + '<div class="admin-oficina-acoes">' + btnBloq + btnPg
      + '<button type="button" class="admin-btn-sec" onclick="adminAcaoConta(\'' + idEsc + '\',\'enviar_recuperacao\')">Enviar recuperar senha</button>'
      + wa + vit + '</div></div>';
  }).join('');
}

function adminFiltrarLista() {
  var lista = window.__adminOficinasCache || [];
  var q = ((document.getElementById('adminBusca') && document.getElementById('adminBusca').value) || '').toLowerCase().trim();
  var f = (document.getElementById('adminFiltro') && document.getElementById('adminFiltro').value) || 'todas';
  var out = lista.filter(function(o) {
    if (f === 'ativas' && o.bloqueada) return false;
    if (f === 'bloqueadas' && !o.bloqueada) return false;
    if (f === 'pagas' && !o.taxa_paga) return false;
    if (f === 'nao_pagas' && o.taxa_paga) return false;
    if (!q) return true;
    var blob = ((o.email || '') + ' ' + (o.nome || '') + ' ' + (o.fone || '') + ' ' + (o.admin_nota || '')).toLowerCase();
    return blob.indexOf(q) >= 0;
  });
  adminRenderLista(out);
}

async function adminToggleManutencao(on) {
  try {
    var sessionRes = await supabaseClient.auth.getSession();
    var token = sessionRes.data.session.access_token;
    var msgEl = document.getElementById('adminManutencaoMsg');
    var mensagem = (msgEl && msgEl.value) || 'Sistema em manutenção. Voltamos em breve.';
    var res = await fetch(ADMIN_SISTEMA_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token,
        'apikey': supabaseKey
      },
      body: JSON.stringify({ action: 'set_manutencao', manutencao: !!on, mensagem: mensagem })
    });
    var json = await res.json().catch(function() { return {}; });
    if (!res.ok) throw new Error(json.error || (json.dica ? json.dica : ('HTTP ' + res.status)));
    if (typeof mostrarToast === 'function') {
      mostrarToast(on ? 'Manutenção ATIVADA' : 'Manutenção desativada', on ? 'aviso' : 'sucesso');
    } else {
      alert(on ? 'Manutenção ATIVADA' : 'Manutenção desativada');
    }
    await carregarPainelAdmin();
  } catch (e) {
    alert('Erro manutenção: ' + (e.message || e));
    await carregarPainelAdmin();
  }
}

async function adminSalvarNota(userId) {
  var el = document.getElementById('nota-' + userId);
  var nota = el ? el.value : '';
  try {
    var sessionRes = await supabaseClient.auth.getSession();
    var token = sessionRes.data.session.access_token;
    var res = await fetch(ADMIN_ACAO_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token, 'apikey': supabaseKey },
      body: JSON.stringify({ action: 'salvar_nota', user_id: userId, nota: nota })
    });
    var json = await res.json().catch(function() { return {}; });
    if (!res.ok) throw new Error(json.error || 'Erro');
    if (typeof mostrarToast === 'function') mostrarToast('Nota salva', 'sucesso');
    else alert('Nota salva');
  } catch (e) {
    alert('Erro ao salvar nota: ' + (e.message || e));
  }
}

function adminExportarCSV() {
  var lista = window.__adminOficinasCache || [];
  if (!lista.length) { alert('Nada para exportar'); return; }
  var sep = ';';
  var lines = [['Email', 'Nome', 'Telefone', 'Profissao', 'Bloqueada', 'Taxa paga', 'Historico', 'Clientes', 'Nota', 'User ID'].join(sep)];
  lista.forEach(function(o) {
    lines.push([
      o.email || '', o.nome || '', o.fone || '', o.profissao || '',
      o.bloqueada ? 'sim' : 'nao', o.taxa_paga ? 'sim' : 'nao',
      o.qtd_historico || 0, o.qtd_clientes || 0,
      String(o.admin_nota || '').replace(/;/g, ','),
      o.user_id || ''
    ].join(sep));
  });
  var blob = new Blob(['\ufeff' + lines.join('\n')], { type: 'text/csv;charset=utf-8;' });
  var a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'aldineicar-oficinas.csv';
  a.click();
}

async function verificarManutencaoAntesLogin() {
  try {
    var res = await fetch(ADMIN_SISTEMA_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'apikey': supabaseKey, 'Authorization': 'Bearer ' + supabaseKey },
      body: JSON.stringify({ action: 'status' })
    });
    var json = await res.json().catch(function() { return {}; });
    return json;
  } catch (e) {
    return { manutencao: false };
  }
}


window.carregarPainelAdmin = carregarPainelAdmin;
