(function ensureAdminMenu() {
  function tick() {
    try {
      if (!supabaseClient || !supabaseClient.auth) return;
      supabaseClient.auth.getUser().then(function(res) {
        var u = res && res.data && res.data.user;
        if (u && u.email && typeof ativarMenuAdminSePermitido === 'function') {
          ativarMenuAdminSePermitido(u.email);
        }
      }).catch(function(){});
    } catch (e) {}
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function(){ setTimeout(tick, 800); setTimeout(tick, 2500); });
  else { setTimeout(tick, 800); setTimeout(tick, 2500); }
})();


async function adminAcaoConta(userId, action) {
  if (!userId || !action) return;
  var msgs = {
    bloquear: 'Bloquear esta conta? Ela não conseguirá entrar no sistema.',
    desbloquear: 'Desbloquear esta conta?',
    marcar_pago: 'Marcar taxa de ativação como PAGA?',
    marcar_nao_pago: 'Marcar taxa como NÃO PAGA?',
    enviar_recuperacao: 'Enviar e-mail de recuperação de senha para esta conta?'
  };
  var msg = msgs[action] || 'Confirmar ação?';
  if (!confirm(msg)) return;
  try {
    var sessionRes = await supabaseClient.auth.getSession();
    var token = sessionRes && sessionRes.data && sessionRes.data.session && sessionRes.data.session.access_token;
    if (!token) throw new Error('Faça login novamente');
    var res = await fetch(ADMIN_ACAO_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token,
        'apikey': (typeof supabaseKey === 'string' ? supabaseKey : '')
      },
      body: JSON.stringify({ user_id: userId, action: action })
    });
    var json = await res.json().catch(function() { return {}; });
    if (!res.ok) throw new Error(json.error || ('HTTP ' + res.status));
    if (action === 'enviar_recuperacao') {
      var txt = 'Recuperação solicitada para ' + (json.email || '') + '.';
      if (json.link) txt += '\n\nLink (se o e-mail não chegar):\n' + json.link;
      alert(txt);
    } else if (typeof mostrarToast === 'function') {
      var t = action === 'bloquear' ? 'Conta bloqueada.'
        : action === 'desbloquear' ? 'Conta desbloqueada.'
        : action === 'marcar_pago' ? 'Taxa marcada como paga.'
        : action === 'marcar_nao_pago' ? 'Taxa marcada como não paga.'
        : 'OK';
      mostrarToast(t, 'sucesso');
    } else {
      alert('OK');
    }
    if (typeof carregarPainelAdmin === 'function') await carregarPainelAdmin();
  } catch (e) {
    console.error(e);
    alert('Erro: ' + (e.message || e));
  }
}
window.adminAcaoConta = adminAcaoConta;

