/* ===== Plano mensal R$15 ===== */
async function obterMetaUsuario() {
  try {
    var res = await supabaseClient.auth.getUser();
    return (res && res.data && res.data.user && res.data.user.user_metadata) || {};
  } catch (e) { return {}; }
}

function formatarDataBRISO(iso) {
  if (!iso) return '—';
  try {
    var d = new Date(iso);
    return d.toLocaleDateString('pt-BR');
  } catch (e) { return String(iso).slice(0, 10); }
}

async function garantirVencimentoInicial() {
  try {
    var res = await supabaseClient.auth.getUser();
    var user = res && res.data && res.data.user;
    if (!user) return;
    var meta = user.user_metadata || {};
    if (meta.assinatura_proximo_vencimento) return;
    if (!(meta.taxa_cadastro_paga || meta.taxa_liberada_admin || meta.assinatura_ativa)) return;
    var base = new Date();
    var prox = new Date(base);
    prox.setDate(prox.getDate() + 30);
    await supabaseClient.auth.updateUser({
      data: {
        assinatura_ativa: true,
        assinatura_status: 'ativa',
        assinatura_proximo_vencimento: prox.toISOString(),
        assinatura_ultimo_pagamento: base.toISOString(),
        taxa_cadastro_paga: true
      }
    });
  } catch (e) { console.warn('[assinatura] garantirVencimento', e); }
}

async function verificarAvisoAssinatura() {
  try {
    if (typeof isEmailAdmin === 'function') {
      var u = await supabaseClient.auth.getUser();
      var em = u && u.data && u.data.user && u.data.user.email;
      if (em && isEmailAdmin(em)) return; // admin isento
    }
    await garantirVencimentoInicial();
    var meta = await obterMetaUsuario();
    var venc = meta.assinatura_proximo_vencimento;
    if (!venc) return;
    var hoje = new Date();
    hoje.setHours(0,0,0,0);
    var dv = new Date(venc);
    dv.setHours(0,0,0,0);
    var dias = Math.round((dv.getTime() - hoje.getTime()) / 86400000);

    var banner = document.getElementById('banner-assinatura');
    if (!banner) {
      banner = document.createElement('div');
      banner.id = 'banner-assinatura';
      banner.className = 'banner-assinatura';
      var header = document.querySelector('header') || document.body;
      if (header.parentNode) header.parentNode.insertBefore(banner, header.nextSibling);
      else document.body.prepend(banner);
    }

    if (dias > 3) {
      banner.style.display = 'none';
      return;
    }

    banner.style.display = 'block';
    if (dias < 0) {
      banner.className = 'banner-assinatura banner-assinatura-critico';
      banner.innerHTML = '<div><strong>Plano vencido</strong> — sua conta pode ser bloqueada. Pague a mensalidade de R$ ' + ASSINATURA_VALOR_MENSAL + ',00.</div>'
        + '<button type="button" onclick="pagarAssinaturaMensal()">Pagar agora</button>';
    } else if (dias === 0) {
      banner.className = 'banner-assinatura banner-assinatura-critico';
      banner.innerHTML = '<div><strong>Vence hoje</strong> — plano mensal R$ ' + ASSINATURA_VALOR_MENSAL + ',00. Vencimento: ' + formatarDataBRISO(venc) + '</div>'
        + '<button type="button" onclick="pagarAssinaturaMensal()">Pagar agora</button>';
    } else {
      banner.className = 'banner-assinatura banner-assinatura-aviso';
      banner.innerHTML = '<div><strong>Faltam ' + dias + ' dia(s)</strong> para o vencimento do plano (R$ ' + ASSINATURA_VALOR_MENSAL + ',00). Vencimento: ' + formatarDataBRISO(venc) + '</div>'
        + '<button type="button" onclick="pagarAssinaturaMensal()">Pagar agora</button>';
    }
  } catch (e) { console.warn(e); }
}

async function pagarAssinaturaMensal() {
  try {
    var sessionRes = await supabaseClient.auth.getSession();
    var token = sessionRes.data.session && sessionRes.data.session.access_token;
    if (!token) { alert('Faça login novamente'); return; }
    if (typeof mostrarToast === 'function') mostrarToast('Gerando pagamento...', 'aviso');
    var res = await fetch(ASSINATURA_PAGAR_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token,
        'apikey': supabaseKey
      },
      body: '{}'
    });
    var json = await res.json().catch(function() { return {}; });
    if (!res.ok) throw new Error(json.error || ('HTTP ' + res.status));
    var url = json.init_point || json.sandbox_init_point;
    if (!url) throw new Error('Link de pagamento não retornado');
    window.location.href = url;
  } catch (e) {
    alert('Erro ao iniciar pagamento: ' + (e.message || e));
  }
}

async function processarRetornoAssinatura() {
  try {
    var params = new URLSearchParams(window.location.search || '');
    var st = params.get('assinatura');
    var paymentId = params.get('payment_id') || params.get('collection_id') || '';
    if (st !== 'ok' && st !== 'pendente' && !paymentId) return;
    if (!supabaseClient || !supabaseClient.auth) return;
    var sessionRes = await supabaseClient.auth.getSession();
    if (!sessionRes.data.session) return;
    if (st === 'ok' || (paymentId && st !== 'falha')) {
      var res = await fetch(ASSINATURA_CONFIRMAR_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + sessionRes.data.session.access_token,
          'apikey': supabaseKey
        },
        body: JSON.stringify({ payment_id: paymentId })
      });
      var json = await res.json().catch(function() { return {}; });
      if (res.ok) {
        alert('Pagamento confirmado! Próximo vencimento: ' + formatarDataBRISO(json.proximo_vencimento));
        try {
          var u = new URL(window.location.href);
          u.searchParams.delete('assinatura');
          u.searchParams.delete('payment_id');
          u.searchParams.delete('collection_id');
          u.searchParams.delete('status');
          u.searchParams.delete('preference_id');
          window.history.replaceState({}, '', u.pathname);
        } catch (e2) {}
        await verificarAvisoAssinatura();
      } else if (st === 'ok') {
        console.warn('confirmar assinatura', json);
      }
    }
  } catch (e) { console.warn(e); }
}

window.pagarAssinaturaMensal = pagarAssinaturaMensal;
window.verificarAvisoAssinatura = verificarAvisoAssinatura;
window.processarRetornoAssinatura = processarRetornoAssinatura;



async function carregarStorageAdmin() {
  var box = document.getElementById('admin-storage-box');
  if (!box) return;
  box.innerHTML = '<p style="color:#94a3b8;font-size:13px;padding:8px 0;">Calculando uso do Storage...</p>';
  try {
    var sessionRes = await supabaseClient.auth.getSession();
    var token = sessionRes.data.session && sessionRes.data.session.access_token;
    if (!token) throw new Error('Sem sessão');
    var res = await fetch(ADMIN_STORAGE_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token,
        'apikey': supabaseKey
      },
      body: JSON.stringify({ action: 'status' })
    });
    var json = await res.json().catch(function() { return {}; });
    if (!res.ok) throw new Error(json.error || ('HTTP ' + res.status));

    var pct = json.percent || 0;
    var alerta = json.alerta || 'ok';
    var barColor = alerta === 'critico' ? '#dc2626' : alerta === 'aviso' ? '#d97706' : '#059669';
    var msg = alerta === 'critico'
      ? 'Storage quase cheio! Considere limpar fotos ou subir de plano.'
      : alerta === 'aviso'
        ? 'Uso elevado. Acompanhe o crescimento das fotos.'
        : 'Uso dentro do esperado (limite Free ~1 GB).';

    var pastas = json.por_pasta || {};
    var pastasHtml = Object.keys(pastas).map(function(k) {
      var mb = Math.round((pastas[k] / (1024 * 1024)) * 10) / 10;
      return '<span class="admin-storage-chip">' + k + ': <b>' + mb + ' MB</b></span>';
    }).join('') || '<span class="admin-storage-chip">Sem arquivos</span>';

    var ranking = json.ranking || [];
    var rankHtml = ranking.length
      ? ranking.map(function(r) {
          var idEsc = String(r.user_id || '').replace(/'/g, "\\'");
          return '<div class="admin-storage-row">'
            + '<div><strong>' + (r.email || r.user_id || '—') + '</strong>'
            + '<div class="admin-oficina-meta">' + (r.files || 0) + ' arquivo(s) · ' + (r.mb || 0) + ' MB</div></div>'
            + '<button type="button" class="admin-btn-danger" onclick="adminLimparStorageUsuario(\'' + idEsc + '\')">Limpar fotos</button>'
            + '</div>';
        }).join('')
      : '<p class="grupo-hint">Nenhum arquivo listado.</p>';

    box.innerHTML =
      '<div class="admin-storage-head">'
      + '<div><strong>📦 Storage — ' + (json.bucket || 'fotos-oficina') + '</strong>'
      + '<div class="admin-oficina-meta">' + msg + '</div></div>'
      + '<div class="admin-storage-nums"><span>' + (json.total_mb || 0) + ' MB</span> / ' + (json.limit_mb || 1024) + ' MB'
      + '<small>' + (json.total_files || 0) + ' arquivos · ' + pct + '%</small></div>'
      + '</div>'
      + '<div class="admin-storage-bar"><div style="width:' + Math.min(100, pct) + '%;background:' + barColor + ';"></div></div>'
      + '<div class="admin-storage-pastas">' + pastasHtml + '</div>'
      + '<p style="font-size:12px;font-weight:700;color:#64748b;margin:12px 0 6px;">Maiores consumidores</p>'
      + '<div class="admin-storage-rank">' + rankHtml + '</div>'
      + '<button type="button" class="admin-btn-sec" style="margin-top:10px;" onclick="carregarStorageAdmin()">Atualizar storage</button>';
  } catch (e) {
    console.error(e);
    box.innerHTML = '<p style="color:#dc2626;font-size:13px;">Erro storage: ' + (e.message || e)
      + '</p><p class="grupo-hint">Faça deploy da Edge Function <b>admin-storage</b>.</p>'
      + '<button type="button" class="admin-btn-sec" onclick="carregarStorageAdmin()">Tentar de novo</button>';
  }
}

async function adminLimparStorageUsuario(userId) {
  if (!userId) return;
  if (!confirm('Apagar TODAS as fotos desta conta no Storage? Isso não desfaz. As URLs antigas vão quebrar.')) return;
  try {
    var sessionRes = await supabaseClient.auth.getSession();
    var token = sessionRes.data.session.access_token;
    var res = await fetch(ADMIN_STORAGE_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token,
        'apikey': supabaseKey
      },
      body: JSON.stringify({ action: 'limpar_usuario', user_id: userId })
    });
    var json = await res.json().catch(function() { return {}; });
    if (!res.ok) throw new Error(json.error || 'Erro');
    alert('Removidos: ' + (json.removidos || 0) + ' arquivo(s).');
    await carregarStorageAdmin();
  } catch (e) {
    alert('Erro ao limpar: ' + (e.message || e));
  }
}

window.carregarStorageAdmin = carregarStorageAdmin;
window.adminLimparStorageUsuario = adminLimparStorageUsuario;



