// Bloqueia agendar / trocar abas se fechada
(function patchVitrineFechadaGuards() {
  function bloquearSeFechada() {
    if (window.__vitrinePublicaFechada) {
      alert('Esta vitrine está fechada no momento.');
      return true;
    }
    return false;
  }
  var tryPatch = function() {
    if (typeof window.abrirModalOrcamentoCliente === 'function' && !window.abrirModalOrcamentoCliente.__fechadaGuard) {
      var orig = window.abrirModalOrcamentoCliente;
      window.abrirModalOrcamentoCliente = function() {
        if (bloquearSeFechada()) return;
        return orig.apply(this, arguments);
      };
      window.abrirModalOrcamentoCliente.__fechadaGuard = true;
    }
    if (typeof window.vitrineMostrarAba === 'function' && !window.vitrineMostrarAba.__fechadaGuard) {
      var orig2 = window.vitrineMostrarAba;
      window.vitrineMostrarAba = function(aba) {
        if (bloquearSeFechada()) return;
        return orig2.apply(this, arguments);
      };
      window.vitrineMostrarAba.__fechadaGuard = true;
    }
  };
  tryPatch();
  setTimeout(tryPatch, 500);
  setTimeout(tryPatch, 2000);
})();



/** Conta admin: menu só com Admin (+ Sair). Contas normais não mudam. */
function aplicarMenuSomenteAdmin(ativo) {
  try {
    var nav = document.getElementById('bn-scroll') || document.getElementById('bottom-nav');
    if (nav) {
      nav.querySelectorAll('.bn-item').forEach(function(btn) {
        var aba = btn.getAttribute('data-aba') || '';
        if (aba === 'admin' || aba === 'sair') {
          btn.style.display = ativo ? 'flex' : (aba === 'admin' ? 'none' : 'flex');
        } else if (ativo) {
          btn.style.display = 'none';
        } else {
          btn.style.display = '';
        }
      });
      var adm = document.getElementById('btn-admin-nav');
      if (adm) adm.style.display = ativo ? 'flex' : 'none';
    }
    // sidebar
    document.querySelectorAll('.sidebar button, .sidebar .side-item').forEach(function(btn) {
      var id = btn.id || '';
      var oc = btn.getAttribute('onclick') || '';
      var da = btn.getAttribute('data-aba') || '';
      var isAdmBtn = (id === 'btn-admin-side' || da === 'admin' || oc.indexOf("mostrarAba('admin')") >= 0);
      var isLogout = btn.classList.contains('btn-logout') || btn.classList.contains('side-logout');
      if (isAdmBtn) {
        if (ativo) { btn.classList.remove('side-hidden'); btn.style.removeProperty('display'); }
        else { btn.classList.add('side-hidden'); btn.style.setProperty('display', 'none', 'important'); }
      } else if (isLogout) {
        btn.classList.remove('side-hidden'); btn.style.removeProperty('display');
      } else if (ativo) {
        btn.classList.add('side-hidden'); btn.style.setProperty('display', 'none', 'important');
      } else {
        btn.classList.remove('side-hidden'); btn.style.removeProperty('display');
      }
    });
    var sideAdm = document.getElementById('btn-admin-side');
    if (sideAdm) {
      if (ativo) { sideAdm.classList.remove('side-hidden'); sideAdm.style.removeProperty('display'); }
      else { sideAdm.classList.add('side-hidden'); sideAdm.style.setProperty('display', 'none', 'important'); }
    }
  } catch (e) {
    console.warn(e);
  }
}

