/** PIX manual com a chave da oficina (sem confirmação automática) */
async function gerarPixManualOficinaFallback(ctx) {
  ctx = ctx || {};
  var infoPix = { chave: '', nome: 'Oficina', cidade: 'BRASIL' };
  try {
    var { data } = await supabaseClient
      .from('user_data')
      .select('dados_oficina')
      .eq('user_id', ctx.idDono)
      .single();
    if (data && data.dados_oficina) {
      infoPix.chave = String(data.dados_oficina.pix || '').replace(/\s/g, '');
      infoPix.nome = data.dados_oficina.nome || 'Oficina';
      infoPix.cidade = (data.dados_oficina.cep || data.dados_oficina.cidade || 'BRASIL').toString().slice(0, 15);
    }
  } catch (e) {}

  if (!infoPix.chave) {
    alert('Esta oficina ainda não configurou PIX nem Mercado Pago. Não é possível pagar online.');
    return;
  }

  var payload = '';
  try {
    if (typeof gerarPayloadPixSimples === 'function') {
      payload = gerarPayloadPixSimples({
        chave: infoPix.chave,
        nome: infoPix.nome,
        cidade: infoPix.cidade || 'BRASIL',
        valor: ctx.total,
        txid: (ctx.externalRef || ('VD' + Date.now())).substring(0, 25)
      });
    }
  } catch (e2) {
    alert('Erro ao montar PIX: ' + (e2.message || e2));
    return;
  }

  var etapaDados = document.getElementById('etapaDadosCompra');
  var etapaPix = document.getElementById('etapaPixCompra');
  if (etapaDados) etapaDados.style.display = 'none';
  if (etapaPix) etapaPix.style.display = 'block';

  var vg = document.getElementById('pixValorGrande');
  if (vg) vg.innerText = 'R$ ' + Number(ctx.total).toFixed(2);
  var ta = document.getElementById('pixCopiaCola');
  if (ta) { ta.style.display = ''; ta.value = payload; }
  var chaveEl = document.getElementById('pixChaveInfo');
  if (chaveEl) chaveEl.innerHTML = 'Chave PIX da oficina: <b style="color:#fff;">' + infoPix.chave + '</b>';
  var pid = document.getElementById('pixPedidoId');
  if (pid) pid.innerText = 'Pedido: ' + (ctx.idVenda || '');

  var qr = document.getElementById('pixQrBox');
  if (qr) {
    qr.innerHTML = '';
    setTimeout(function() {
      if (typeof desenharQrSimples === 'function') desenharQrSimples(payload);
    }, 40);
  }

  // remove box automático se existir
  var auto = document.getElementById('lojaPixAutoBox');
  if (auto) auto.remove();

  // aviso manual
  if (!document.getElementById('lojaPixManualAviso')) {
    var av = document.createElement('div');
    av.id = 'lojaPixManualAviso';
    av.style.cssText = 'margin:12px 0;padding:12px;background:#422006;border:1px solid #f59e0b;border-radius:10px;';
    av.innerHTML = '<p style="margin:0;font-size:12px;color:#fde68a;line-height:1.45;"><b>PIX da oficina (confirmação manual).</b><br>Pague e aguarde a oficina confirmar o recebimento. Para confirmação automática, a oficina conecta o Mercado Pago em Configurar Oficina.</p>';
    if (etapaPix) etapaPix.insertBefore(av, etapaPix.firstChild);
  }

  if (typeof mostrarToast === 'function') mostrarToast('PIX da oficina gerado (modo manual)', 'aviso');
}
window.gerarPixManualOficinaFallback = gerarPixManualOficinaFallback;



/* ===== Conectar Mercado Pago (OAuth — um clique) ===== */
async function conectarMercadoPagoOficina() {
  try {
    var sessionRes = await supabaseClient.auth.getSession();
    var token = sessionRes.data.session && sessionRes.data.session.access_token;
    if (!token) { alert('Faça login primeiro'); return; }
    if (typeof mostrarToast === 'function') mostrarToast('Abrindo Mercado Pago...', 'aviso');
    var res = await fetch(MP_OAUTH_INICIAR_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token,
        'apikey': supabaseKey
      },
      body: '{}'
    });
    var json = await res.json().catch(function() { return {}; });
    if (!res.ok) throw new Error(json.error || ('HTTP ' + res.status));
    if (!json.auth_url) throw new Error('URL de autorização não retornada');
    window.location.href = json.auth_url;
  } catch (e) {
    alert('Não foi possível conectar: ' + (e.message || e) + '\n\nPeça ao suporte para configurar MP_CLIENT_ID e MP_CLIENT_SECRET.');
  }
}

async function desconectarMercadoPagoOficina() {
  if (!confirm('Desconectar Mercado Pago? As vendas da loja voltam ao PIX manual.')) return;
  try {
    var sessionRes = await supabaseClient.auth.getSession();
    var token = sessionRes.data.session.access_token;
    var res = await fetch(MP_OAUTH_DESCONECTAR_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token,
        'apikey': supabaseKey
      },
      body: '{}'
    });
    var json = await res.json().catch(function() { return {}; });
    if (!res.ok) throw new Error(json.error || 'Erro');
    if (dadosOficina) {
      delete dadosOficina.mp_access_token;
      delete dadosOficina.mp_refresh_token;
      dadosOficina.mp_loja_ativo = false;
    }
    var st = document.getElementById('oficinaMpStatus');
    if (st) st.innerHTML = '<span style="color:#fbbf24;">Desconectado — modo PIX manual</span>';
    var btnC = document.getElementById('btnConectarMp');
    var btnD = document.getElementById('btnDesconectarMp');
    if (btnC) btnC.style.display = '';
    if (btnD) btnD.style.display = 'none';
    if (typeof salvarNoBanco === 'function') await salvarNoBanco(true);
    if (typeof mostrarToast === 'function') mostrarToast('Mercado Pago desconectado', 'aviso');
  } catch (e) {
    alert('Erro: ' + (e.message || e));
  }
}

function atualizarUIMercadoPagoOficina() {
  var ativo = !!(dadosOficina && (dadosOficina.mp_loja_ativo || (dadosOficina.mp_access_token && String(dadosOficina.mp_access_token).indexOf('APP_USR-') === 0)));
  var st = document.getElementById('oficinaMpStatus');
  var btnC = document.getElementById('btnConectarMp');
  var btnD = document.getElementById('btnDesconectarMp');
  if (st) {
    st.innerHTML = ativo
      ? '<span style="color:#22c55e;font-weight:700;">✓ Conta Mercado Pago conectada — PIX automático na sua conta</span>'
      : '<span style="color:#94a3b8;">Não conectado — vendas usam PIX manual (você confirma)</span>';
  }
  if (btnC) btnC.style.display = ativo ? 'none' : '';
  if (btnD) btnD.style.display = ativo ? '' : 'none';
}

function processarRetornoMpOAuth() {
  try {
    var params = new URLSearchParams(window.location.search || '');
    var c = params.get('mp_conectado');
    if (c === null) return;
    if (c === '1') {
      if (typeof mostrarToast === 'function') mostrarToast('Mercado Pago conectado com sucesso!', 'sucesso');
      else alert('Mercado Pago conectado! O dinheiro das vendas cairá na sua conta.');
      if (dadosOficina) dadosOficina.mp_loja_ativo = true;
      atualizarUIMercadoPagoOficina();
      // recarrega dados
      if (typeof usuarioAtualId !== 'undefined' && usuarioAtualId && typeof carregarDadosDoUsuario === 'function') {
        carregarDadosDoUsuario(usuarioAtualId);
      }
    } else if (c === '0') {
      alert('Não foi possível conectar: ' + (params.get('msg') || 'tente de novo'));
    }
    try {
      var u = new URL(window.location.href);
      u.searchParams.delete('mp_conectado');
      u.searchParams.delete('msg');
      window.history.replaceState({}, '', u.pathname + (u.search || ''));
    } catch (e2) {}
  } catch (e) {}
}

window.conectarMercadoPagoOficina = conectarMercadoPagoOficina;
window.desconectarMercadoPagoOficina = desconectarMercadoPagoOficina;
window.atualizarUIMercadoPagoOficina = atualizarUIMercadoPagoOficina;

(function() {
  function run() { processarRetornoMpOAuth(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run);
  else run();
})();


/** Nunca apagar tokens MP da oficina ao salvar dados locais */
function preservarCredenciaisMp(destino, origem) {
  if (!destino || typeof destino !== 'object') return destino;
  var src = origem || destino;
  var keys = ['mp_access_token','mp_refresh_token','mp_user_id','mp_token_expires_at','mp_loja_ativo','mp_conectado_em'];
  keys.forEach(function(k) {
    if (src[k] != null && src[k] !== '' && (destino[k] == null || destino[k] === '')) {
      destino[k] = src[k];
    }
  });
  // se destino não tem token mas window.__mpBackup tem
  if ((!destino.mp_access_token || String(destino.mp_access_token).length < 20) && window.__mpBackup) {
    keys.forEach(function(k) {
      if (window.__mpBackup[k] != null) destino[k] = window.__mpBackup[k];
    });
  }
  if (destino.mp_access_token && String(destino.mp_access_token).length >= 20) {
    window.__mpBackup = {
      mp_access_token: destino.mp_access_token,
      mp_refresh_token: destino.mp_refresh_token,
      mp_user_id: destino.mp_user_id,
      mp_token_expires_at: destino.mp_token_expires_at,
      mp_loja_ativo: true
    };
  }
  return destino;
}


