/* ===== Tema claro / escuro ===== */
var TEMA_KEY = 'aldineicar_tema';
function obterTemaAtual() {
  try {
    var t = localStorage.getItem(TEMA_KEY);
    if (t === 'dark' || t === 'light') return t;
  } catch (e) {}
  return 'light';
}
function aplicarTema(tema) {
  tema = (tema === 'dark') ? 'dark' : 'light';
  document.documentElement.setAttribute('data-theme', tema);
  try { localStorage.setItem(TEMA_KEY, tema); } catch (e) {}
  var btn = document.getElementById('btnToggleTema');
  if (btn) {
    btn.textContent = tema === 'dark' ? '☀️ Tema claro' : '🌙 Tema escuro';
  }
  var sel = document.getElementById('selectTemaApp');
  if (sel) sel.value = tema;
}
function alternarTemaApp() {
  var atual = obterTemaAtual();
  aplicarTema(atual === 'dark' ? 'light' : 'dark');
  if (typeof mostrarToast === 'function') {
    mostrarToast(obterTemaAtual() === 'dark' ? 'Tema escuro ativado' : 'Tema claro ativado', 'sucesso');
  }
}
function definirTemaApp(tema) {
  aplicarTema(tema);
}
window.alternarTemaApp = alternarTemaApp;
window.definirTemaApp = definirTemaApp;
window.aplicarTema = aplicarTema;
(function initTema() {
  function go() { aplicarTema(obterTemaAtual()); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', go);
  else go();
})();

/* Corrige botões claros no tema escuro (inline styles) */
function corrigirBotoesTemaEscuro() {
  try {
    if (document.documentElement.getAttribute('data-theme') !== 'dark') return;
    var nodes = document.querySelectorAll('button, .btn, [type="button"]');
    nodes.forEach(function(btn) {
      if (!btn || btn.closest('.bn-item') && btn.classList.contains('bn-item')) return;
      var st = (btn.getAttribute('style') || '').toLowerCase();
      var cs = window.getComputedStyle ? window.getComputedStyle(btn) : null;
      var bg = (cs && cs.backgroundColor) ? cs.backgroundColor : '';
      // rgb branco / quase branco / amarelo claro
      var isLight = false;
      if (bg) {
        var m = bg.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
        if (m) {
          var r = +m[1], g = +m[2], b = +m[3];
          if (r > 220 && g > 220 && b > 220) isLight = true;
          if (r > 240 && g > 200 && b < 120) isLight = true; // amarelo
        }
      }
      if (st.indexOf('background:#fff') >= 0 || st.indexOf('background: #fff') >= 0 ||
          st.indexOf('background:#f8') >= 0 || st.indexOf('background:#f1') >= 0 ||
          st.indexOf('background:#ffd') >= 0 || st.indexOf('background:white') >= 0) {
        isLight = true;
      }
      if (isLight) {
        btn.style.setProperty('background', '#334155', 'important');
        btn.style.setProperty('color', '#f8fafc', 'important');
        btn.style.setProperty('border-color', '#64748b', 'important');
      }
      // texto preto forçado
      var color = cs ? cs.color : '';
      if (color) {
        var mc = color.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
        if (mc) {
          var r2 = +mc[1], g2 = +mc[2], b2 = +mc[3];
          if (r2 < 50 && g2 < 50 && b2 < 50) {
            btn.style.setProperty('color', '#f8fafc', 'important');
          }
        }
      }
    });
  } catch (e) {}
}
window.corrigirBotoesTemaEscuro = corrigirBotoesTemaEscuro;

(function patchAplicarTema() {
  var orig = window.aplicarTema;
  if (typeof orig !== 'function') return;
  window.aplicarTema = function(tema) {
    orig(tema);
    setTimeout(corrigirBotoesTemaEscuro, 50);
    setTimeout(corrigirBotoesTemaEscuro, 400);
  };
})();

// após trocar de aba, reaplicar
(function patchMostrarAbaTema() {
  var orig = window.mostrarAba;
  if (typeof orig !== 'function') return;
  window.mostrarAba = function(nome) {
    var r = orig.apply(this, arguments);
    if (document.documentElement.getAttribute('data-theme') === 'dark') {
      setTimeout(corrigirBotoesTemaEscuro, 80);
    }
    return r;
  };
})();
